static const char* viewerText(const char* de, const char* en) { const String language=palaUiLanguage(); if(language=="de") return de; if(language=="sk" && !strcmp(en,"Tasks"))return "Úlohy"; if(language=="sk" && !strcmp(en,"Calendar"))return "Kalendár"; const char* codes[]={"fr","es","it","pl","cs","ru","uk","nl","pt","sk"}; int index=-1; for(int i=0;i<10;i++) if(language==codes[i]){index=i;break;} if(index<0)return en; for(const auto& row:kViewerTranslations)if(!strcmp(row.en,en))return row.values[index]; return en;}
static const char* viewerLocale() { const String language=palaUiLanguage(); if(language=="sk")return "sk-SK"; if(language=="de")return "de-DE"; if(language=="fr")return "fr-FR"; if(language=="es")return "es-ES"; if(language=="it")return "it-IT"; if(language=="pl")return "pl-PL"; if(language=="cs")return "cs-CZ"; if(language=="ru")return "ru-RU"; if(language=="uk")return "uk-UA"; if(language=="nl")return "nl-NL"; if(language=="pt")return "pt-PT"; return "en-GB";}
